CREATE TABLE IF NOT EXISTS metadata (name VARCHAR(100) PRIMARY KEY, meta_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS write_lock (id INTEGER PRIMARY KEY);
INSERT INTO write_lock (id) SELECT 1 WHERE NOT EXISTS (SELECT 1 FROM write_lock WHERE id=1);
CREATE TABLE IF NOT EXISTS well (id VARCHAR(100) PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, version BIGINT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS well_actions (well_id VARCHAR(100) PRIMARY KEY REFERENCES well(id) ON DELETE CASCADE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS model_version (id VARCHAR(100) PRIMARY KEY, created_at VARCHAR(100) NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS training_dataset (id INTEGER PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS training_run (id VARCHAR(100) PRIMARY KEY, started_at VARCHAR(100) NOT NULL, status VARCHAR(30) NOT NULL, fingerprint VARCHAR(100), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_snapshot (id VARCHAR(100) PRIMARY KEY, created_at VARCHAR(100) NOT NULL, payload TEXT NOT NULL);
